<?php
namespace Tests\Feature;
use App\Enums\ApprovalStatus;use App\Enums\ApprovalType;use App\Enums\UserRole;use App\Models\ApprovalRequest;use App\Models\ExpenseCategory;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Laravel\Sanctum\Sanctum;use Tests\TestCase;
class NextStaffFinanceApiTest extends TestCase{use RefreshDatabase;
public function test_admin_can_request_expense_without_direct_financial_mutation():void{$admin=User::factory()->create(['role'=>UserRole::Admin]);$category=ExpenseCategory::create(['name'=>'Operasional Next']);Sanctum::actingAs($admin,['staff:finance']);$this->postJson('/api/v1/staff/expenses',['expense_category_id'=>$category->id,'amount'=>50000,'description'=>'Internet kantor Next','expense_date'=>today()->toDateString(),'payment_method'=>'transfer'])->assertStatus(202);$this->assertDatabaseCount('expenses',0);$this->assertDatabaseHas('approval_requests',['type'=>ApprovalType::FinancialExpense->value,'status'=>ApprovalStatus::Pending->value,'requested_by'=>$admin->id]);$this->getJson('/api/v1/staff/expenses')->assertOk()->assertJsonPath('data.categories.0.name','Operasional Next');}
public function test_daily_report_returns_combined_zero_state_and_validates_date():void{$owner=User::factory()->create(['role'=>UserRole::Owner]);Sanctum::actingAs($owner,['staff:finance']);$this->getJson('/api/v1/staff/reports/daily?date='.today()->toDateString())->assertOk()->assertJsonPath('data.summary.gross_revenue',0)->assertJsonPath('data.summary.net_cash',0)->assertJsonCount(0,'data.topups');$this->getJson('/api/v1/staff/reports/daily?date=invalid')->assertUnprocessable()->assertJsonValidationErrors('date');}
public function test_finance_access_requires_owner_or_admin_and_ability():void{$cashier=User::factory()->create(['role'=>UserRole::Cashier]);Sanctum::actingAs($cashier,['staff:finance']);$this->getJson('/api/v1/staff/expenses')->assertForbidden();$owner=User::factory()->create(['role'=>UserRole::Owner]);Sanctum::actingAs($owner,['staff:dashboard']);$this->getJson('/api/v1/staff/reports/daily')->assertForbidden();}
}